import React from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { HashRouter, Routes, Route } from "react-router-dom";
import Home from "../pages/Home"; // Trỏ ra thư mục cha để vào pages
import "../scss/style.scss";      // Trỏ ra thư mục cha để vào scss

export default function App() {
  return (
    <HashRouter>
      <div className="App">
        <Routes>
          {/* Cấu hình đường dẫn đơn giản nhất */}
          <Route path="/" element={<Home />} />
          <Route path="*" element={<Home />} />
        </Routes>
      </div>
    </HashRouter>
  );
}